        get filteredTransactions() {
            const q = this.searchQuery.trim().toLowerCase();
            if (!q) return this.activeTransactions;
            return this.activeTransactions.filter(item =>
                item.name.toLowerCase().includes(q) || item.email.toLowerCase().includes(q)
            );
        },
        get totalPages() {
            return Math.max(1, Math.ceil(this.filteredTransactions.length / this.itemsPerPage));
        },
        get safeCurrentPage() {
            return Math.min(this.currentPage, this.totalPages);
        },
        get paginatedTransactions() {
            const start = (this.safeCurrentPage - 1) * this.itemsPerPage;
            return this.filteredTransactions.slice(start, start + this.itemsPerPage);
        },
        get pages() {
            const cp = this.safeCurrentPage;
            const tp = this.totalPages;
            if (tp <= 7) return Array.from({ length: tp }, (_, i) => i + 1);
            if (cp <= 4) return [1, 2, 3, 4, 5, 'ellipsis-end', tp];
            if (cp >= tp - 3) return [1, 'ellipsis-start', tp - 4, tp - 3, tp - 2, tp - 1, tp];
            return [1, 'ellipsis-start', cp - 1, cp, cp + 1, 'ellipsis-end', tp];
        },
